import json

# Correct input: 16x10 grid with 2s at rows 0, 2, 5 in column 0
test_input = []
for r in range(16):
    row = []
    for c in range(10):
        if r == 0 or r == 2 or r == 5:
            row.append([4] + [3]*9)  # row with 4 at start
        else:
            row.append([3]*10)
    test_input.append(row[0])  # take first element of inner list

# Build output: convert 2s to 1s  
output = []
for r in range(16):
    for c in range(10):
        if r == 0 or r == 2 or r == 5:
            output.append(1 if c == 0 else 3)
        else:
            output.append(3)
    output.append('\n')  # separator

# Actually let's just build clean grid
output = [[1 if (r == 0 or r == 2 or r == 5) and c == 0 else 3 for c in range(10)] for r in range(16)]
print(json.dumps({"action": "submit", "grid": output}))
